import{_ as s,C as o,o as n,c as r,j as a,a as i,E as h,ah as d}from"./chunks/framework.Be4_4mPW.js";const f=JSON.parse('{"title":"Turns and the map","description":"","frontmatter":{},"headers":[],"relativePath":"turns-and-map.md","filePath":"turns-and-map.md"}'),l={name:"turns-and-map.md"};function m(p,e,u,g,c,w){const t=o("Mermaid");return n(),r("div",null,[e[0]||(e[0]=a("h1",{id:"turns-and-the-map",tabindex:"-1"},[i("Turns and the map "),a("a",{class:"header-anchor",href:"#turns-and-the-map","aria-label":'Permalink to "Turns and the map"'},"​")],-1)),e[1]||(e[1]=a("p",null,"A game runs in turns, and every game has a map. The admin, who is the umpire, moves the game from turn to turn and keeps the map's picture of the world up to date. Players see both change as it happens. Both were added to version 1 in Phase 5, at the product owner's request.",-1)),h(t,{code:"flowchart%20LR%0A%20%20%20%20subgraph%20Admin%5B%22The%20umpire's%20game%20view%22%5D%0A%20%20%20%20%20%20%20%20TurnPanel%5B%22Turn%20panel%3A%20move%20the%20game%20on%22%5D%0A%20%20%20%20%20%20%20%20Editor%5B%22Map%20editor%3A%20add%2C%20move%2C%20edit%2C%20delete%22%5D%0A%20%20%20%20%20%20%20%20Draft%5B(%22Draft%3A%20this%20browser%20only%22)%5D%0A%20%20%20%20%20%20%20%20Summary%5B%22Change%20summary%3A%20confirm%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Server%5B%22XMPP%20server%22%5D%0A%20%20%20%20%20%20%20%20State%5B(%22Turn%20and%20phase%22)%5D%0A%20%20%20%20%20%20%20%20MapRoom%5B(%22Map%20room%3A%20one%20message%20per%20world%20state%22)%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Player%5B%22Every%20player%22%5D%0A%20%20%20%20%20%20%20%20Panel%5B%22Turn%20panel%22%5D%0A%20%20%20%20%20%20%20%20Composer%5B%22Message%20entry%3A%20paused%20in%20adjudication%22%5D%0A%20%20%20%20%20%20%20%20Map%5B%22Map%20and%20table%2C%20read%20only%22%5D%0A%20%20%20%20end%0A%20%20%20%20Editor%20--%3E%20Draft%20--%3E%20Summary%0A%20%20%20%20TurnPanel%20--%3E%20Summary%0A%20%20%20%20Summary%20--%3E%7Cwith%20a%20phase%20change%7C%20State%0A%20%20%20%20Summary%20--%3E%7Cpublish%7C%20MapRoom%0A%20%20%20%20State%20--%3E%20Panel%20%26%20Composer%0A%20%20%20%20MapRoom%20--%3E%20Map%0A"}),e[2]||(e[2]=d('<h2 id="turns" tabindex="-1">Turns <a class="header-anchor" href="#turns" aria-label="Permalink to &quot;Turns&quot;">​</a></h2><p>Each turn has a planning phase and then an adjudication phase. The turn panel, at the top of the out-of-game column, shows the turn number and the phase to everyone, and updates the moment it changes.</p><ul><li><strong>Only the admin moves the game on:</strong> from the turn panel in the game view, or from the turn control in the admin backend&#39;s header. Each change asks for a confirmation first, which says what happens next.</li><li><strong>During adjudication</strong>, roles outside the White Force cannot post. Their message entry is paused with a note that says why, and anything they had typed is kept for the next planning phase. The White Force and the admin keep posting, so umpires can give rulings.</li><li><strong>Advisory, not enforced.</strong> The pause is applied by the app, not by the server: a modified client could still post during adjudication. Version 1 accepts that; the umpires see every message.</li></ul><h2 id="the-map-room" tabindex="-1">The map room <a class="header-anchor" href="#the-map-room" aria-label="Permalink to &quot;The map room&quot;">​</a></h2><p>Every game has exactly one map room, and every role can open it. It shows the <strong>world state</strong>: each force&#39;s units and platforms as standard military symbols (MIL-STD-2525 or APP-6), with a title, force, category, position, state, health and fuel.</p><ul><li><strong>Map or table.</strong> Select a symbol to see its details, or switch to the table: the same assets, sorted by force, usable from the keyboard alone. The map pans with the arrow keys and zooms with plus and minus.</li><li><strong>Read only for players.</strong> Only the admin&#39;s world states count. If anyone else posts something into the map room, every client ignores it.</li><li><strong>Always the latest.</strong> A player who opens the map, or comes back after a reload, sees the newest world state the admin has published; later ones replace it as they arrive.</li><li><strong>Base map.</strong> The map draws its background from a tile server that the deployment chooses. A tile server learns which area each player looks at, so on an internal network the operator decides which one to use, or none: without one, the map shows the assets on a plain background. The demo on this site uses OpenStreetMap&#39;s tiles.</li></ul><h2 id="editing-the-world-state" tabindex="-1">Editing the world state <a class="header-anchor" href="#editing-the-world-state" aria-label="Permalink to &quot;Editing the world state&quot;">​</a></h2><p>Only the admin edits the map, in the map room of the umpire&#39;s game view. Players and the admin&#39;s preview of a role never see the editing tools.</p><ul><li><strong>Add</strong> an asset with &quot;Add asset…&quot;, which opens a form, or with &quot;Place on map&quot; and a click where it goes.</li><li><strong>Move</strong> an asset by dragging its symbol, or, from the keyboard, by changing its latitude and longitude in its form.</li><li><strong>Edit</strong> any of its details in the form, which previews the symbol as its code is typed and checks every field.</li><li><strong>Delete</strong> it from its details, after a confirmation.</li></ul><p>Edits build up as a <strong>draft held only in this browser</strong>. While the draft differs from what players see, the map says how many assets have unpublished changes and that clearing the browser&#39;s data or changing device loses them. If the game was reset since the draft began, the map warns that the draft may belong to the earlier game.</p><h3 id="publishing" tabindex="-1">Publishing <a class="header-anchor" href="#publishing" aria-label="Permalink to &quot;Publishing&quot;">​</a></h3><p>The admin publishes the draft in one of two ways:</p><ul><li><strong>With a phase change.</strong> Starting the next phase or turn shows the change summary in the confirmation and publishes the world state with it, stamped with the new turn. A phase change with no edits publishes no world state.</li><li><strong>At any time,</strong> with &quot;Publish world state&quot;, for example to set up the starting position before play, or to correct a mistake in the middle of a turn.</li></ul><p>Either way the admin first sees a summary: the assets added, removed and changed, with the fields that changed and their old and new values. Every publish sends the whole world state as one message, so a player who joins late needs only the latest one. A world state may be up to 500 KB as a message: about 1,700 assets of typical size, or nearly 1,000 with every text field at its longest. The editor refuses a larger one with its size and what to do.</p><h3 id="moving-a-game-with-its-map" tabindex="-1">Moving a game with its map <a class="header-anchor" href="#moving-a-game-with-its-map" aria-label="Permalink to &quot;Moving a game with its map&quot;">​</a></h3><p>A design export carries the world state: the admin&#39;s draft if this browser holds one, otherwise the latest published state. The export says when the file holds an unpublished draft, and when it holds no world state because the published one could not be read. Importing a design makes its world state the admin&#39;s draft, which players see only once it is published.</p><h2 id="layouts-and-design-changes" tabindex="-1">Layouts and design changes <a class="header-anchor" href="#layouts-and-design-changes" aria-label="Permalink to &quot;Layouts and design changes&quot;">​</a></h2><p>Players arrange their rooms in a dockable workspace, saved in their browser. A design change resets every online player&#39;s layout to the default, with a notice, only when it is <strong>structural</strong>: a room added or removed, or a change to which rooms a role can see or write in. Renaming, re-ordering, themes, objectives and templates never reset a layout, and nor does adding or removing a role: only the rooms of roles already in the game are compared.</p>',18))])}const b=s(l,[["render",m]]);export{f as __pageData,b as default};
